import { Link, useLocation, useNavigate } from "react-router-dom";
import { FaUserCircle } from "react-icons/fa";

export default function Navbar() {
  const location = useLocation();
  const nav = useNavigate();

  const openProfile = () => {
    alert(
      "👤 My Profile\n\nName: Bhavya\nEmail: bhavya@gmail.com\nRole: User"
    );
  };

  return (
    <nav style={styles.navbar}>
      {/* LOGO */}
      <h2 style={styles.logo}>Poll App</h2>

      {/* LINKS */}
      <div style={styles.links}>
        <Link to="/home" style={styles.link}>
          <span style={location.pathname === "/home" ? styles.active : null}>
            Home
          </span>
        </Link>

        {/* CHANGED TEXT */}
        <Link to="/create-poll" style={styles.link}>
          <span
            style={
              location.pathname === "/create-poll"
                ? styles.active
                : null
            }
          >
            Polls
          </span>
        </Link>

        {/* CHANGED TEXT */}
        <Link to="/create-survey" style={styles.link}>
          <span
            style={
              location.pathname === "/create-survey"
                ? styles.active
                : null
            }
          >
            Surveys
          </span>
        </Link>
      </div>

      {/* PROFILE ICON */}
      <div style={styles.profile} onClick={openProfile}>
        <FaUserCircle style={styles.profileIcon} />
      </div>
    </nav>
  );
}

const styles = {
  navbar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "14px 28px",
    background: "rgba(15, 23, 42, 0.9)",
    backdropFilter: "blur(10px)",
    color: "#fff",
    position: "sticky",
    top: 0,
    zIndex: 1000,
    boxShadow: "0 4px 10px rgba(0,0,0,0.3)",
  },

  logo: {
    margin: 0,
    fontSize: "22px",
    fontWeight: "bold",
    cursor: "pointer",
  },

  links: {
    display: "flex",
    gap: "30px",
  },

  link: {
    textDecoration: "none",
    fontSize: "15px",
    color: "#cbd5e1",
  },

  active: {
    color: "#38bdf8",
    borderBottom: "2px solid #38bdf8",
    paddingBottom: "4px",
  },

  profile: {
    background: "#1e293b",
    padding: "8px",
    borderRadius: "50%",
    cursor: "pointer",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },

  profileIcon: {
    fontSize: "30px",
    color: "#38bdf8",
  },
};
